"""matplotlib.backends.backend_webagg — webagg backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_webagg import
FigureCanvasWebAgg`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasWebAgg = _make_canvas('FigureCanvasWebAgg', 'png')
FigureManagerWebAgg = _make_manager('FigureManagerWebAgg')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasWebAgg
FigureManager = FigureManagerWebAgg

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendWebAgg', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Added: missing public names (stub classes/funcs) ────────
class WebAggApplication:
    """Stub: real matplotlib defines this in the webagg backend."""
    def __init__(self, *args, **kwargs): pass

def ipython_inline_display(figure): return ""

webagg_server_thread = None
